package com.cinenest.rooms.internal;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import static org.assertj.core.api.Assertions.*;
class BannerPolicyTest {
 @Test void defaultDenyAndProfileBoundary(){var env=new MockEnvironment();assertThat(new BannerPolicy(false,env).enabled()).isFalse();assertThatThrownBy(()->new BannerPolicy(false,env).require()).isInstanceOf(RoomFailure.class);assertThatThrownBy(()->new BannerPolicy(true,env)).isInstanceOf(IllegalStateException.class);env.setActiveProfiles("local-synthetic");assertThat(new BannerPolicy(true,env).enabled()).isTrue();}
 @Test void exactContentFieldAndScheduleValidation(){var m=new HashMap<String,Object>(Map.of("title","Test","description","Plain text","altText","Cinema concept","assetId","hero","assetVersion",1,"startsAt","2026-11-01T18:00:00+05:30","endsAt","2026-11-01T20:00:00+05:30","displayOrder",1,"linkTarget","NONE"));assertThat(BannerPolicy.content(m).startsAt().toString()).isEqualTo("2026-11-01T12:30:00Z");for(var e:Map.of("title","<script>","startsAt","2026-11-01T18:00","endsAt","2020-01-01T00:00:00Z","displayOrder",1.5,"linkTarget","javascript:alert(1)","assetVersion",2).entrySet()){var bad=new HashMap<>(m);bad.put(e.getKey(),e.getValue());assertThatThrownBy(()->BannerPolicy.content(bad)).isInstanceOf(RoomFailure.class);}m.put("published",true);assertThatThrownBy(()->BannerPolicy.content(m)).isInstanceOf(RoomFailure.class);assertThatThrownBy(()->new BannerAssets().resolve("../../bank" )).isInstanceOf(RoomFailure.class);}
}
